-- 100_missing_summon_creatures.sql -- map 751 extension, DB step 39.
--
-- GENERATED by Custom/Documentation/scripts/gen_summon_and_wander_repairs.py.
--
-- THE SPELL -> CREATURE DEPENDENCY. One level deeper than the item -> spell one
-- 94_/88_ already dealt with, and it fires at RUNTIME, not at boot:
--   Creature::Create(): creature template (guidlow: 2474, entry: 50374) does not exist.
--   Auras: unknown creature id = 50380 ... From Spell Aura Transform in Spell ID = 93460
--
-- Neither creature is spawned anywhere, summoned by a SmartAI action, listed in
-- creature_summon_groups, or used as a vehicle accessory -- checked all four.
-- They are summoned BY THE SPELLS 88_ downported: a spell carries the creature id
-- in EffectMiscValue for SPELL_EFFECT_SUMMON (28) / SUMMON_PET (56) /
-- TRANS_DOOR (90) / SUMMON_OBJECT (112), and for SPELL_AURA_TRANSFORM (aura 56,
-- which needs the creature only for its modelid -- hence the "only need its
-- modelid" wording in that log line).
--
-- Auditing spell_dbc for every such reference: 75 missing creature ids, 68 of them
-- in cata_world, 66 of those named by a spell 88_ added. Those 66 are imported here
-- at PLAIN Cata ids -- that is the id the spell effect names, and unlike spawned
-- content a summon target cannot be moved to the +4,100,000 band without editing
-- the spell itself.
--
-- Anything with no cata_world row is NOT faked; the tail of this file lists what
-- is still unresolved so it stays visible.

-- ---------------------------------------------------------------------------
-- 1. creature_template -- copied from cata_world, columns named explicitly.
--    A `SELECT *` cannot be used: the two schemas differ (creature_template
--    drift is documented), so only the columns both sides share are copied and
--    the rest take our defaults.
-- ---------------------------------------------------------------------------
-- A REGULAR scratch table, not TEMPORARY, and not by accident: MySQL cannot
-- reference a TEMPORARY table more than once in one query (error 1137,
-- "Can't reopen table"), and the verification UNION below reads it three
-- times. It is dropped again at the end of this file.
--
-- A snapshot table is REQUIRED here rather than repeating the sub-select: the
-- predicate is "not yet in creature_template", which the INSERT below makes
-- false. Recomputing it afterwards would return an empty set and the
-- verification would silently report zero of everything.
DROP TABLE IF EXISTS `_dc_missing_summons`;
CREATE TABLE `_dc_missing_summons` (`entry` INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO `_dc_missing_summons` (`entry`)
SELECT DISTINCT z.cre FROM (
  SELECT `ID` s, `EffectMiscValue_1` cre FROM `spell_dbc` WHERE `EffectMiscValue_1`>0 AND (`Effect_1` IN (28,56,90,112) OR `EffectAura_1`=56)
  UNION ALL SELECT `ID`, `EffectMiscValue_2` FROM `spell_dbc` WHERE `EffectMiscValue_2`>0 AND (`Effect_2` IN (28,56,90,112) OR `EffectAura_2`=56)
  UNION ALL SELECT `ID`, `EffectMiscValue_3` FROM `spell_dbc` WHERE `EffectMiscValue_3`>0 AND (`Effect_3` IN (28,56,90,112) OR `EffectAura_3`=56)
) z
WHERE z.s >= 70956
  AND NOT EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = z.cre)
  AND EXISTS (SELECT 1 FROM `cata_world`.`creature_template` c WHERE c.`entry` = z.cre);

INSERT INTO `creature_template`
  (`entry`, `name`, `subname`, `minlevel`, `maxlevel`, `faction`, `npcflag`, `speed_walk`, `speed_run`, `rank`, `dmgschool`, `BaseAttackTime`, `RangeAttackTime`, `unit_class`, `unit_flags`, `unit_flags2`, `family`, `type`, `type_flags`, `MovementType`, `HoverHeight`, `RegenHealth`, `flags_extra`)
SELECT c.`entry`, CONVERT(c.`name` USING utf8mb4) COLLATE utf8mb4_general_ci, CONVERT(c.`subname` USING utf8mb4) COLLATE utf8mb4_general_ci, c.`minlevel`, c.`maxlevel`, c.`faction`, c.`npcflag`, c.`speed_walk`, c.`speed_run`, c.`rank`, c.`dmgschool`, c.`BaseAttackTime`, c.`RangeAttackTime`, c.`unit_class`, c.`unit_flags`, c.`unit_flags2`, c.`family`, c.`type`, c.`type_flags`, c.`MovementType`, c.`HoverHeight`, c.`RegenHealth`, c.`flags_extra`
FROM `cata_world`.`creature_template` c JOIN `_dc_missing_summons` m ON m.`entry` = c.`entry`
WHERE NOT EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = c.`entry`);

-- ---------------------------------------------------------------------------
-- 2. creature_template_model -- the display layer. Without it the creature
--    loads but renders as nothing (see the three-layer display rule).
-- ---------------------------------------------------------------------------
INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`)
SELECT m.`entry`, 0, c.`modelid1`, 1, 1 FROM `cata_world`.`creature_template` c JOIN `_dc_missing_summons` m ON m.`entry`=c.`entry`
WHERE c.`modelid1` > 0
  AND NOT EXISTS (SELECT 1 FROM `creature_template_model` x WHERE x.`CreatureID` = m.`entry` AND x.`Idx` = 0);

-- must be paired with a CreatureDisplayInfo row or the model id resolves to
-- nothing; the verification block below reports any that are not covered.

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
SELECT 'summon targets imported' AS what, COUNT(*) AS n FROM `_dc_missing_summons`
UNION ALL SELECT '  ...now present in creature_template (want the same)', COUNT(*)
  FROM `_dc_missing_summons` m JOIN `creature_template` t ON t.`entry` = m.`entry`
UNION ALL SELECT '  ...with a display model row', COUNT(*)
  FROM `_dc_missing_summons` m JOIN `creature_template_model` x ON x.`CreatureID` = m.`entry`
UNION ALL SELECT 'spell summon/transform targets STILL missing', COUNT(DISTINCT z.cre)
  FROM (
  SELECT `ID` s, `EffectMiscValue_1` cre FROM `spell_dbc` WHERE `EffectMiscValue_1`>0 AND (`Effect_1` IN (28,56,90,112) OR `EffectAura_1`=56)
  UNION ALL SELECT `ID`, `EffectMiscValue_2` FROM `spell_dbc` WHERE `EffectMiscValue_2`>0 AND (`Effect_2` IN (28,56,90,112) OR `EffectAura_2`=56)
  UNION ALL SELECT `ID`, `EffectMiscValue_3` FROM `spell_dbc` WHERE `EffectMiscValue_3`>0 AND (`Effect_3` IN (28,56,90,112) OR `EffectAura_3`=56)
) z
  WHERE NOT EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = z.cre);

-- what is left, and why -- these have NO cata_world row to copy, so they are
-- reported rather than invented. Expect a handful; they belong to spells that
-- were already present before 88_.
SELECT 'UNRESOLVED: no source for this summon target' AS problem,
       z.cre AS creature, GROUP_CONCAT(DISTINCT z.s ORDER BY z.s) AS from_spells
FROM (
  SELECT `ID` s, `EffectMiscValue_1` cre FROM `spell_dbc` WHERE `EffectMiscValue_1`>0 AND (`Effect_1` IN (28,56,90,112) OR `EffectAura_1`=56)
  UNION ALL SELECT `ID`, `EffectMiscValue_2` FROM `spell_dbc` WHERE `EffectMiscValue_2`>0 AND (`Effect_2` IN (28,56,90,112) OR `EffectAura_2`=56)
  UNION ALL SELECT `ID`, `EffectMiscValue_3` FROM `spell_dbc` WHERE `EffectMiscValue_3`>0 AND (`Effect_3` IN (28,56,90,112) OR `EffectAura_3`=56)
) z
WHERE NOT EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = z.cre)
GROUP BY z.cre ORDER BY z.cre;

-- ---------------------------------------------------------------------------
-- DISPLAY COVERAGE -- READ BEFORE CALLING THIS DONE
-- Importing the template stops "creature template does not exist" and stops the
-- transform aura complaining. It does NOT make the summon VISIBLE. A creature
-- needs three layers: creature_template_model (written above), creature_model_info,
-- and a CreatureDisplayInfo row in the DBC.
--
-- Only 5 of the 66 models appear in the `creaturedisplayinfo_dbc` overlay -- and
-- that overlay is an AUDIT source, not the authority: the server reads its binary
-- data/dbc/CreatureDisplayInfo.dbc, proven for this exact table on 2026-08-02.
-- So the query below is a LOWER BOUND on what still needs display work; check the
-- shipped DBC for the real answer. Expect a display pass to follow, as after every
-- previous creature import.
-- ---------------------------------------------------------------------------
SELECT 'imported summon with no display row in the overlay' AS problem,
       m.`entry`, x.`CreatureDisplayID`
FROM `_dc_missing_summons` m
JOIN `creature_template_model` x ON x.`CreatureID` = m.`entry`
WHERE NOT EXISTS (SELECT 1 FROM `creaturedisplayinfo_dbc` d WHERE d.`ID` = x.`CreatureDisplayID`)
ORDER BY m.`entry`;

DROP TABLE IF EXISTS `_dc_missing_summons`;
